use vstd::prelude::*;

verus! {

fn empty(n: u8) -> (result: Vec<f64>)
    ensures
        result.len() == n as usize,
{
    let target = n as usize;
    let mut result: Vec<f64> = Vec::with_capacity(target);

    while result.len() < target
        invariant
            result.len() <= target,
        decreases target - result.len(),
    {
        // Any value is acceptable; only the length matters.
        result.push(0.0);
    }

    result
}

} // verus!

